DROP TABLE IF EXISTS `rooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rooms` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `property_id` bigint(20) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `max_guests` int(11) NOT NULL DEFAULT 2,
  `max_adults` int(11) NOT NULL DEFAULT 2,
  `max_children` int(11) NOT NULL DEFAULT 1,
  `room_size_sqm` int(11) DEFAULT NULL,
  `bed_type` varchar(255) NOT NULL DEFAULT '1 King Bed',
  `view_type` varchar(100) DEFAULT 'City View',
  `bathroom_count` int(11) NOT NULL DEFAULT 1,
  `bathroom_features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`bathroom_features`)),
  `smoking_policy` varchar(50) NOT NULL DEFAULT 'Non-Smoking',
  `balcony_type` varchar(100) DEFAULT 'Private Balcony',
  `extra_bed_allowed` tinyint(1) NOT NULL DEFAULT 0,
  `price_per_night` decimal(10,2) NOT NULL,
  `total_rooms` int(11) NOT NULL DEFAULT 10,
  `breakfast_included` tinyint(1) NOT NULL DEFAULT 0,
  `free_cancellation` tinyint(1) NOT NULL DEFAULT 1,
  `facilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`facilities`)),
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`images`)),
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_room_property_price` (`property_id`,`price_per_night`),
  KEY `idx_rooms_prop_status` (`property_id`,`status`),
  KEY `idx_rooms_prop_price` (`property_id`,`price_per_night`),
  KEY `idx_rooms_prop_capacity` (`property_id`,`max_adults`,`max_children`),
  CONSTRAINT `rooms_property_id_foreign` FOREIGN KEY (`property_id`) REFERENCES `properties` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
